\[\infer[\!\!{\lnot\text{i}^{_1}}]{\lnot \exists x P(x)}{\infer[\!\!{\exists\text{e}^{_2} }]{\bot}{\big[\exists x P(x)\big]^{_{1}} & \infer[\!\!{\lnot\text{e}}]{\bot}{{\big[P(a)\big]^{_{2}}}&{\infer[\!\!\forall\text{e}]{\lnot P(a)}{{\forall x \lnot P(x)}}}}}}\]
